urlset:
{% for url in urlset %}

  {{ url.location }}

  {# Çoklu dil desteği #}
  {% if url.item.alternates %}
    {% for lang, href in url.item.alternates %}

    {% endfor %}
  {% endif %}

  {% if url.lastmod %}{{ url.lastmod|date:"c" }}{% endif %}
  {% if url.changefreq %}{{ url.changefreq }}{% endif %}
  {% if url.priority %}{{ url.priority }}{% endif %}

{% endfor %}
